{"code":"import pandas as pd
import numpy as np

raw = pd.read_csv('raw_responses.csv')
pipeline = pd.read_csv('pipeline_output.csv')

# Let's write our python scorer
def round_half_up(val):
    # val is a float
    # halves always round up: 4.5 -> 5, 10.5 -> 11
    # We can use decimal or np.floor(val + 0.5) for positive numbers
    return int(np.floor(val + 0.5))

def score_phq9(row):
    items = [f'phq9_{i}' for i in range(1, 10)]
    vals = []
    for item in items:
        v = row[item]
        if pd.isna(v) or v not in [0, 1, 2, 3]:
            vals.append(np.nan)
        else:
            vals.append(int(v))

    n_missing = pd.isna(vals).sum()
    if n_missing >= 2:
        return np.nan, np.nan, np.nan, None
    elif n_missing == 1:
        ans_sum = np.nansum(vals)
        scaled = ans_sum * 9 / 8.0
        total = round_half_up(scaled)
        prorated = True
    else:
        total = int(np.nansum(vals))
        prorated = False

    # band
    if total <= 4:
        band = 'none-minimal'
    elif total <= 9:
        band = 'mild'
    elif total <= 14:
        band = 'moderate'
    elif total <= 19:
        band = 'moderately severe'
    else:
        band = 'severe'

    # self harm flag
    q9 = row['phq9_9']
    if pd.isna(q9) or q9 not in [0, 1, 2, 3]:
        flag = None
    else:
        flag = True if int(q9) > 0 else False

    return total, band, prorated, flag

def score_gad7(row):
    items = [f'gad7_{i}' for i in range(1, 8)]
    vals = []
    for item in items:
        v = row[item]
        if pd.isna(v) or v not in [0, 1, 2, 3]:
            vals.append(np.nan)
        else:
            vals.append(int(v))

    n_missing = pd.isna(vals).sum()
    if n_missing >= 2:
        return np.nan, np.nan, np.nan
    elif n_missing == 1:
        ans_sum = np.nansum(vals)
        scaled = ans_sum * 7 / 6.0
        total = round_half_up(scaled)
        prorated = True
    else:
        total = int(np.nansum(vals))
        prorated = False

    if total <= 4:
        band = 'minimal'
    elif total <= 9:
        band = 'mild'
    elif total <= 14:
        band = 'moderate'
    else:
        band = 'severe'

    return total, band, prorated

def score_rses(row):
    items = [f'rses_{i}' for i in range(1, 11)]
    rev_items = [3, 5, 8, 9, 10]
    vals = []
    for i in range(1, 11):
        v = row[f'rses_{i}']
        if pd.isna(v) or v not in [0, 1, 2, 3]:
            vals.append(np.nan)
        else:
            val = int(v)
            if i in rev_items:
                val = 3 - val
            vals.append(val)

    n_missing = pd.isna(vals).sum()
    if n_missing >= 2:
        return np.nan, np.nan
    elif n_missing == 1:
        ans_sum = np.nansum(vals)
        scaled = ans_sum * 10 / 9.0
        total = round_half_up(scaled)
        prorated = True
    else:
        total = int(np.nansum(vals))
        prorated = False

    return total, prorated

results = []
for idx, row in raw.iterrows():
    p_tot, p_band, p_pro, p_flag = score_phq9(row)
    g_tot, g_band, g_pro = score_gad7(row)
    r_tot, r_pro = score_rses(row)
    results.append({
        'respondent_id': row['respondent_id'],
        'phq9_total': p_tot,
        'phq9_band': p_band,
        'phq9_prorated': p_pro,
        'phq9_self_harm_flag': p_flag,
        'gad7_total': g_tot,
        'gad7_band': g_band,
        'gad7_prorated': g_pro,
        'rses_total': r_tot,
        'rses_prorated': r_pro
    })

my_df = pd.DataFrame(results)

# Compare with pipeline
for col in pipeline.columns:
    if col == 'respondent_id':
        continue
    # compare series
    match = my_df[col].equals(pipeline[col])
    print(f"Column {col} exact match: {match}")
    if not match:
        # count mismatches (treating NaN == NaN)
        s1 = my_df[col]
        s2 = pipeline[col]
        mismatches = ~(s1.astype(object) == s2.astype(object)) & ~(s1.isna() & s2.isna())
        print(f"  Number of mismatches: {mismatches.sum()}")
        if mismatches.sum() > 0:
            diff_df = pd.DataFrame({'respondent': raw['respondent_id'], 'mine': s1, 'pipe': s2})
            print(diff_df[mismatches].head(10))
