import pandas as pd
import numpy as np

raw = pd.read_csv('raw_responses.csv')
pipeline = pd.read_csv('pipeline_output.csv')

def round_half_up(val):
    return int(np.floor(val + 0.5))

def score_all(row):
    # PHQ9
    p_vals = []
    for i in range(1, 10):
        v = row[f'phq9_{i}']
        if pd.isna(v) or v not in [0, 1, 2, 3]:
            p_vals.append(np.nan)
        else:
            p_vals.append(int(v))
    p_missing = pd.isna(p_vals).sum()
    if p_missing >= 2:
        p_tot, p_band, p_pro = np.nan, np.nan, np.nan
    elif p_missing == 1:
        p_tot = round_half_up(np.nansum(p_vals) * 9 / 8.0)
        p_pro = True
    else:
        p_tot = int(np.nansum(p_vals))
        p_pro = False

    if pd.isna(p_tot):
        p_band = np.nan
    else:
        if p_tot <= 4: p_band = 'none-minimal'
        elif p_tot <= 9: p_band = 'mild'
        elif p_tot <= 14: p_band = 'moderate'
        elif p_tot <= 19: p_band = 'moderately severe'
        else: p_band = 'severe'

    q9 = row['phq9_9']
    if pd.isna(q9) or q9 not in [0, 1, 2, 3]:
        p_flag = np.nan
    else:
        p_flag = True if int(q9) > 0 else False

    # GAD7
    g_vals = []
    for i in range(1, 8):
        v = row[f'gad7_{i}']
        if pd.isna(v) or v not in [0, 1, 2, 3]:
            g_vals.append(np.nan)
        else:
            g_vals.append(int(v))
    g_missing = pd.isna(g_vals).sum()
    if g_missing >= 2:
        g_tot, g_band, g_pro = np.nan, np.nan, np.nan
    elif g_missing == 1:
        g_tot = round_half_up(np.nansum(g_vals) * 7 / 6.0)
        g_pro = True
    else:
        g_tot = int(np.nansum(g_vals))
        g_pro = False

    if pd.isna(g_tot):
        g_band = np.nan
    else:
        if g_tot <= 4: g_band = 'minimal'
        elif g_tot <= 9: g_band = 'mild'
        elif g_tot <= 14: g_band = 'moderate'
        else: g_band = 'severe'

    # RSES (with pipeline mistake: reversing items 2, 5, 6, 8, 9 instead of 3, 5, 8, 9, 10)
    r_vals = []
    rev_items = [2, 5, 6, 8, 9]
    for i in range(1, 11):
        v = row[f'rses_{i}']
        if pd.isna(v) or v not in [0, 1, 2, 3]:
            r_vals.append(np.nan)
        else:
            val = int(v)
            if i in rev_items:
                val = 3 - val
            r_vals.append(val)
    r_missing = pd.isna(r_vals).sum()
    if r_missing >= 2:
        r_tot, r_pro = np.nan, np.nan
    elif r_missing == 1:
        r_tot = round_half_up(np.nansum(r_vals) * 10 / 9.0)
        r_pro = True
    else:
        r_tot = int(np.nansum(r_vals))
        r_pro = False

    return pd.Series({
        'respondent_id': row['respondent_id'],
        'phq9_total': p_tot,
        'phq9_band': p_band,
        'phq9_prorated': p_pro,
