        'gad7_total': g_tot,
        'gad7_band': g_band,
        'gad7_prorated': g_pro,
        'rses_total': r_tot,
        'rses_prorated': r_pro
    })

my_out = raw.apply(score_all, axis=1)

for col in pipeline.columns:
    if col == 'respondent_id':
        continue
    s1 = my_out[col]
    s2 = pipeline[col]
    match = s1.equals(s2) or ((s1.isna() == s2.isna()) & (s1.fillna(0) == s2.fillna(0)).all())
    print(f"Column {col} matches pipeline: {match}")
